package com.oms.order.service;

import com.oms.messaging.*;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.stereotype.Component;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;

/** One platform request per delivery; the durable phase owns the page and per-application checkpoint. */
@Component @ConditionalOnProperty(name="oms.messaging.enabled",havingValue="true")
public class ExchangePullMessage implements MessageHandler {
 @Resource ExchangeSync sync;@Resource ExchangePlatformClient platform;
 public String type(){return "EXCHANGE_PULL";}
 public Map<String,Object> context(String c,Map<String,Object> m){Map<String,Object> t=sync.rawTask(c,number(m,"business_id"),false);return map("path","/oms-order/management","kind","EXCHANGE","tab","tasks","taskId",t.get("id"));}
 boolean terminal(Map<String,Object> t,Map<String,Object> m){return number(t,"work_version")!=number(m,"business_version")||Arrays.asList("COMPLETED","FAILED").contains(text(t,"state"));}
 List<Map<String,Object>> pending(String c,long id){return sync.repository.db().query("SELECT * FROM oms_exchange_sync_item WHERE company_code=? AND task_id=? AND result IN ('PENDING','FAILED') ORDER BY (result='FAILED'),id LIMIT 1",ROW,c,id);}
 public List<String> rateKeys(String c,Map<String,Object> m){Map<String,Object> t=sync.rawTask(c,number(m,"business_id"),false);if(terminal(t,m)||("DETAIL".equals(text(t,"phase"))&&pending(c,number(t,"id")).isEmpty()))return Collections.emptyList();List<String> keys=data(platform.rateKeys(c,number(t,"channel_id"),SecurityConstants.INNER));require(keys!=null&&keys.size()==2&&keys.stream().allMatch(k->k!=null&&k.matches("[a-f0-9]{64}")),"店铺调用限流身份无效");return keys;}
 Map<String,Object> fence(String c,long channel,String lease,Map<String,Object> before){sync.fence(c,channel,lease);Map<String,Object> t=sync.rawTask(c,number(before,"id"),true);require(number(t,"work_version")==number(before,"work_version")&&number(t,"page_no")==number(before,"page_no")&&text(t,"phase").equals(text(before,"phase"))&&!Arrays.asList("COMPLETED","FAILED").contains(text(t,"state")),"换货同步版本或分页阶段已变化");return t;}
 void finishPage(String c,Map<String,Object> t){long id=number(t,"id");if(!pending(c,id).isEmpty())return;sync.repository.db().update("UPDATE oms_exchange_config SET last_error='' WHERE company_code=? AND channel_id=?",c,t.get("channel_id"));boolean done=number(t,"page_complete")==1;sync.repository.db().update("UPDATE oms_exchange_sync SET state=?,phase=?,page_no=page_no+?,last_error='' WHERE company_code=? AND id=?",done?"COMPLETED":"RUNNING",done?"DETAIL":"LIST",done?0:1,c,id);if(done&&"AUTO".equals(text(t,"mode")))sync.repository.db().update("UPDATE oms_exchange_config SET cursor_time=GREATEST(cursor_time,?),last_error='',next_run=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND channel_id=?",t.get("end_time"),c,t.get("channel_id"));}
 void counts(String c,long id){Map<String,Object> r=sync.repository.db().queryForMap("SELECT COALESCE(SUM(result<>'PENDING'),0) n,COALESCE(SUM(result='NEW'),0) fresh,COALESCE(SUM(result='UPDATED'),0) changed,COALESCE(SUM(result IN ('DUPLICATE','OLDER')),0) same,COALESCE(SUM(result IN ('FAILED','INVALID','CONFLICT')),0) failed FROM oms_exchange_sync_item WHERE company_code=? AND task_id=?",c,id);sync.repository.db().update("UPDATE oms_exchange_sync SET synced_count=?,new_count=?,updated_count=?,unchanged_count=?,failed_count=? WHERE company_code=? AND id=?",r.get("n"),r.get("fresh"),r.get("changed"),r.get("same"),r.get("failed"),c,id);}
 @SuppressWarnings("unchecked") public Outcome handle(String c,Map<String,Object> m){long id=number(m,"business_id");Map<String,Object> before=sync.rawTask(c,id,false);if(number(before,"work_version")!=number(m,"business_version"))return Outcome.done("换货同步已有新版本，原通知结束");if("COMPLETED".equals(text(before,"state")))return Outcome.done("平台换货拉取完成；转单独立跟踪");if("FAILED".equals(text(before,"state")))return Outcome.failed(text(before,"last_error"));long channel=number(before,"channel_id");String lease=token();if(!sync.claim(c,channel,lease))return OrderPullMessage.waiting("同店铺换货正在处理，等待租约释放",5);
  try{sync.tx().execute(s->{fence(c,channel,lease,before);sync.repository.db().update("UPDATE oms_exchange_sync SET state='RUNNING' WHERE company_code=? AND id=?",c,id);return null;});
   if("LIST".equals(text(before,"phase"))){Map<String,Object> page=sync.exchanges.call(c,channel,"LIST",map("fields",ExchangeService.FIELDS.replace(",refund_phase","").replace(",operation_contraint",""),"page_no",before.get("page_no"),"page_size",30,"start_gmt_modified_time",before.get("start_time"),"end_gmt_modifed_time",before.get("end_time")));Object records=page.get("records");require(records instanceof List&&((List<?>)records).size()<=30,"平台换货列表响应异常");List<Map<String,Object>> rows=(List<Map<String,Object>>)records;Set<String> ids=new LinkedHashSet<>();for(Map<String,Object> r:rows){String dispute=text(r,"dispute_id");require(dispute.matches("[1-9][0-9]{0,63}"),"平台换货列表缺少可靠单号");ids.add(dispute);}
    sync.tx().execute(s->{Map<String,Object> t=fence(c,channel,lease,before);for(String dispute:ids)sync.repository.db().update("INSERT IGNORE INTO oms_exchange_sync_item(company_code,task_id,dispute_id,result,message) VALUES (?,?,?,'PENDING','等待详情拉取')",c,id,dispute);sync.repository.db().update("UPDATE oms_exchange_sync SET phase='DETAIL',page_complete=?,last_error='' WHERE company_code=? AND id=?",rows.size()<30?1:0,c,id);t.put("page_complete",rows.size()<30?1:0);finishPage(c,t);return null;});
   }else{List<Map<String,Object>> items=pending(c,id);if(items.isEmpty())sync.tx().execute(s->{Map<String,Object> t=fence(c,channel,lease,before);finishPage(c,t);return null;});else{String dispute=text(items.get(0),"dispute_id");try{Map<String,Object> result=sync.exchanges.call(c,channel,"DETAIL",map("dispute_id",dispute,"fields",ExchangeService.FIELDS));Map<String,Object> payload=ExchangeService.object(result.get("exchange"));require(dispute.equals(text(payload,"dispute_id")),"平台响应换货单号与请求不一致");sync.tx().execute(s->{Map<String,Object> t=fence(c,channel,lease,before);Map<String,Object> saved=sync.platformExchanges.ingest(c,channel,payload,text(before,"actor"));sync.repository.db().update("UPDATE oms_exchange_sync_item SET result=?,platform_exchange_id=?,exchange_id=?,message=? WHERE company_code=? AND task_id=? AND dispute_id=?",saved.get("outcome"),saved.get("id"),saved.get("business_exchange_id"),Arrays.asList("INVALID","CONFLICT").contains(text(saved,"outcome"))?"平台来源待核对；已保留快照":"平台申请已保存；转单进度独立展示",c,id,dispute);counts(c,id);finishPage(c,t);return null;});}
    catch(RuntimeException error){String reason=MessageProblem.summary(error);sync.tx().execute(s->{fence(c,channel,lease,before);sync.repository.db().update("UPDATE oms_exchange_sync_item SET result='FAILED',message=? WHERE company_code=? AND task_id=? AND dispute_id=?",reason,c,id,dispute);counts(c,id);return null;});throw error;}}}
   return "COMPLETED".equals(text(sync.rawTask(c,id,false),"state"))?Outcome.done("平台换货已保存；业务转单由独立队列处理"):Outcome.again("分页或逐单详情进度已保存，继续未完成项",5);
  }catch(RuntimeException error){String reason=MessageProblem.summary(error);sync.repository.db().update("UPDATE oms_exchange_sync SET attempts=attempts+1,last_error=? WHERE company_code=? AND id=? AND work_version=? AND state IN ('PENDING','RUNNING','RETRY')",reason,c,id,m.get("business_version"));sync.repository.db().update("UPDATE oms_exchange_config SET last_error=? WHERE company_code=? AND channel_id=? AND lease_token=?",reason,c,channel,lease);return Outcome.retry(reason,15).problem(MessageProblem.exception(error));}finally{sync.release(c,channel,lease);}
 }
 public void failed(String c,Map<String,Object> m,String reason){sync.repository.db().update("UPDATE oms_exchange_sync SET state='FAILED',last_error=? WHERE company_code=? AND id=? AND work_version=? AND state IN ('PENDING','RUNNING','RETRY')",reason.substring(0,Math.min(480,reason.length())),c,number(m,"business_id"),number(m,"business_version"));}
 public void replay(String c,Map<String,Object> m,String actor,String reason){sync.retry(c,number(m,"business_id"));}
}
